function shippingCostCents(weightGrams: number, destination: Address): number {
  const base = destination.country === "JP" ? 500 : 2500;
  return base + Math.ceil(weightGrams / 500) * 100;
}

function isDeliverable(destination: Address): boolean {
  return destination.country !== "" && destination.postalCode.length >= 3;
}

function estimatedDeliveryDays(destination: Address): number {
  if (destination.country === "JP" && destination.postalCode.startsWith("1")) return 0;
  return destination.country === "JP" ? 2 : 9;
}

function isDeliverableToday(destination: Address): boolean {
  return isDeliverable(destination) && estimatedDeliveryDays(destination) === 0;
}

function percentOff(amount: number, percent: number): number {
  return Math.round(amount * (1 - percent / 100));
}

function applyCouponCode(amount: number, code: string): number {
  if (code === "SAVE10") return percentOff(amount, 10);
  if (code === "SAVE20") return percentOff(amount, 20);
  return amount;
}

function isCouponExpired(issuedAt: Date, validDays: number): boolean {
  const ageMs = Date.now() - issuedAt.getTime();
  return ageMs > validDays * 24 * 60 * 60 * 1000;
}

function bestDiscount(amount: number, codes: string[]): number {
  return codes.reduce((best, code) => Math.min(best, applyCouponCode(amount, code)), amount);
}

