pub fn split_evenly(total_cents: i64, ways: i64) -> Vec<i64> {
    if ways <= 0 {
        return Vec::new();
    }
    let base = total_cents / ways;
    let remainder = total_cents % ways;
    (0..ways).map(|i| if i < remainder { base + 1 } else { base }).collect()
}

